  "revision_action": "strengthen",
  "supportive_card_ids": ["C18", "C34", "C67", "C103", "C72", "C46", "C50", "C19", "C161", "C190", "C184", "C151"],
  "contradictory_card_ids": ["C108", "C49", "C122", "C125", "C127", "C120"],
  "prediction_basis_card_ids": ["C18", "C34", "C67", "C103", "C46", "C161", "C190", "C184"],
  "claims": [
    {
      "claim": "Omadacycline, the closest supplied tetracycline-class analog to the query fluorocycline, has measured absolute oral bioavailability of 34.5% in healthy adults after a 300 mg fasted standard tablet, 31.2% in CF patients, and 31% in monkeys, all above the 20% threshold.",
      "card_ids": ["C18", "C34", "C67", "C103", "C72"]
    },
    {
      "claim": "Tetracycline has human oral bioavailability reported as 75%, >70%, and 80–90%, and L3 oral exposure records show substantial absorption (500 mg tetracycline alone: geometric mean Cmax 4.57 µg/mL and AUC0-∞ 67.4 µg·h/mL in healthy volunteers), supporting that the tetracycline core can achieve F≥20% in humans.",
      "card_ids": ["C46", "C50", "C19", "C184", "C161", "C190"]
    },
    {
      "claim": "L3 minocycline oral exposure in dogs (AUC 11.9 µg·h/mL fed vs 19.85 µg·h/mL fasted) confirms oral absorption for a close tetracycline analog, though it is not a direct F measurement.",
      "card_ids": ["C151"]
    },
    {
      "claim": "The query's computed low-logD/high-TPSA liabilities are shared by omadacycline, which still achieves F≈34.5%; the physicochemical prior is therefore not affirmative evidence of F<20%.",
      "card_ids": ["C18", "C34"]
    },
    {
      "claim": "No direct eravacycline-specific absolute oral bioavailability record is supplied; the high prediction rests on class-level transfer and means F≥20% is better supported, not that a specific F value or formulation is established.",
      "card_ids": ["C18", "C46"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C161", "C190", "C184", "C171", "C151"]
    }
  ],
  "evidence_gaps": [
    "No direct eravacycline-specific absolute oral bioavailability record is present in the supplied cards; the decision relies on transfer from omadacycline and tetracycline.",
    "The target species is not explicitly specified; omadacycline lacks oral bioavailability in rodents (C108) and tetracycline F is low in some animal models, so a rodent-based endpoint would substantially weaken the high prediction.",
    "Formulation and prandial conditions for the query are unspecified; omadacycline F ranges from 0.5% for a slow-dissolution tablet to 34.5% for a standard fasted tablet (C49, C18).",
    "Potential efflux, first-pass metabolism, and active uptake for eravacycline are not directly measured in the supplied evidence.",
    "Most L3 oral AUC/Cmax records are for unrelated molecules (DHE, fluoroquinolones, DA-8010, nintedanib, etc.) and were not used as evidence for the query."
  ],
  "decision_summary": "Predicted high (F≥20%) because the query is a fluorocycline tetracycline and the closest supplied empirical contexts—omadacycline (34.5% human, 31.2% CF, 31% monkey) and tetracycline (75% human)—show oral bioavailability above threshold; L3 oral exposure records for tetracycline (Cmax 4.57 µg/mL, AUC0-∞ 67.4 µg·h/mL at 500 mg) and minocycline (oral AUC in dogs) reinforce that the tetracycline class is orally absorbed; the low physicochemical prior is not affirmative evidence of F<20% and no new contradictory eravacycline-specific evidence was supplied."
}

